Q: Make a 3d image preview on my web site made of some images of the 3d object from different angles A: <p>The answer i found for who'd like is the following</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const threeDObj = document.querySelector(".threeDObj");
let mouseMoveListenerActive = false;

        function mouseDownListener() {
            if (!mouseMoveListenerActive) {
                threeDObj.addEventListener("mousemove", mouseMoveListener);
                mouseMoveListenerActive = true;
            }
            console.log("Mouse down");
            threeDObj.innerHTML = "Mouse down";
        }

        function mouseMoveListener(event) {
            console.log("Mouse position: " + event.clientX + ", " + event.clientY);
            threeDObj.innerHTML = "Mouse position: " + event.clientX + ", " + event.clientY;
        }

        function mouseUpListener() {
            if (mouseMoveListenerActive) {
                threeDObj.removeEventListener("mousemove", mouseMoveListener);
                mouseMoveListenerActive = false;
            }
            console.log("Mouse up");
            threeDObj.innerHTML = "Mouse up";
        }

        threeDObj.addEventListener("mousedown", mouseDownListener);
        threeDObj.addEventListener("mouseup", mouseUpListener);</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>.threeDObj {
            user-select: none;
            -webkit-user-drag: none;
            -moz-user-select: none;
            -webkit-user-select: none;
            width: 1000px;
            height: 1000px;
        }</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>    &lt;p class="threeDObj"&gt;previous&lt;/p&gt;</code></pre>
</div>
</div>
</p>
<p>now instead of changing the text i can change the image that i want it to appear based on 3x16 array of img src's</p>
<p>Thanks nicholas for helping me!</p>
